
CREATE TABLE `finance_entries` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `branchId` VARCHAR(191) NOT NULL, `accountId` VARCHAR(191) NULL, `kind` VARCHAR(40) NOT NULL, `name` VARCHAR(150) NOT NULL, `amount` DECIMAL(12,2) NOT NULL, `entryDate` DATETIME(3) NOT NULL, `referenceId` VARCHAR(191) NULL, `notes` TEXT NULL, `requestId` VARCHAR(191) NOT NULL, `createdById` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(`id`), UNIQUE INDEX `finance_entries_branchId_requestId_kind_key`(`branchId`,`requestId`,`kind`), INDEX `finance_entries_businessId_branchId_accountId_entryDate_idx`(`businessId`,`branchId`,`accountId`,`entryDate`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `loan_accounts` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `branchId` VARCHAR(191) NOT NULL, `name` VARCHAR(150) NOT NULL, `principal` DECIMAL(12,2) NOT NULL, `openingDate` DATETIME(3) NOT NULL, `notes` TEXT NULL, `requestId` VARCHAR(191) NOT NULL, `createdById` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(`id`), UNIQUE INDEX `loan_accounts_branchId_requestId_key`(`branchId`,`requestId`), INDEX `loan_accounts_businessId_branchId_name_idx`(`businessId`,`branchId`,`name`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `loan_payments` (`id` VARCHAR(191) NOT NULL, `loanId` VARCHAR(191) NOT NULL, `principal` DECIMAL(12,2) NOT NULL, `interest` DECIMAL(12,2) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `paidAt` DATETIME(3) NOT NULL, `requestId` VARCHAR(191) NOT NULL, `createdById` VARCHAR(191) NOT NULL, PRIMARY KEY(`id`), UNIQUE INDEX `loan_payments_loanId_requestId_key`(`loanId`,`requestId`), CONSTRAINT `loan_payments_loanId_fkey` FOREIGN KEY(`loanId`) REFERENCES `loan_accounts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `income_categories` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `branchId` VARCHAR(191) NOT NULL, `name` VARCHAR(100) NOT NULL, PRIMARY KEY(`id`), UNIQUE INDEX `income_categories_branchId_name_key`(`branchId`,`name`), INDEX `income_categories_businessId_branchId_idx`(`businessId`,`branchId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `cheque_events` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `branchId` VARCHAR(191) NOT NULL, `paymentId` VARCHAR(191) NOT NULL, `action` VARCHAR(20) NOT NULL, `accountId` VARCHAR(191) NULL, `requestId` VARCHAR(191) NOT NULL, `createdById` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(`id`), UNIQUE INDEX `cheque_events_paymentId_requestId_key`(`paymentId`,`requestId`), INDEX `cheque_events_businessId_branchId_paymentId_createdAt_idx`(`businessId`,`branchId`,`paymentId`,`createdAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
